import{_ as t,o as e,c as s,a4 as i}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"TrueTime / HLC / attestation","description":"","frontmatter":{},"headers":[],"relativePath":"distributed/clock/physical.md","filePath":"distributed/clock/physical.md","lastUpdated":1788475713000}'),n={name:"distributed/clock/physical.md"};function o(r,a,l,c,d,p){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="truetime-hlc-attestation" tabindex="-1">TrueTime / HLC / attestation <a class="header-anchor" href="#truetime-hlc-attestation" aria-label="Permalink to &quot;TrueTime / HLC / attestation&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>Google Spanner (2012 OSDI) 是全球第一个跨数据中心实现 <strong>External Consistency</strong> (linearizability + serializable + real-time 顺序) 的数据库——靠 <strong>TrueTime API</strong> <code>TT.now() returns [earliest, latest]</code> 区间, 配合 <strong>commit-wait</strong> (等至 latest &gt; commit_ts 才 reply client) 避免 stale read。 TrueTime 通过 <strong>GPS + Atomic Reference Clock</strong> 在数据中心每几 ms 同步物理时间, 给 [earliest, latest] 区间不确定性 ~7ms。 CockroachDB / YugaByte 用 HLC 替代 TrueTime, NTP-bound skew 250ms。本章梳理 TrueTime API 形式, commit-wait 算法, Spanner Paxos group + 2PC 的分布事务流程, TrueTime 的硬件 attestation (GPS/原子钟故障检测), 与 HLC 的对比。</p><hr><h2 id="一、物理时钟的-distributed-problem" tabindex="-1">一、物理时钟的 distributed problem <a class="header-anchor" href="#一、物理时钟的-distributed-problem" aria-label="Permalink to &quot;一、物理时钟的 distributed problem&quot;">​</a></h2><h3 id="wall-clock-skew" tabindex="-1">Wall clock skew <a class="header-anchor" href="#wall-clock-skew" aria-label="Permalink to &quot;Wall clock skew&quot;">​</a></h3><p>NTP 同步精度跨数据中心 ~50-100ms (粗), PTP 同步 ~1ms (严谨), GPS ~100us-1ms (条件好), 原子钟 ~微秒-nanosecond。任何方式都会<strong>引入 skew</strong>, 必须 bounded 才能用 commit-wait algorithm。</p><h3 id="同步为什么不可能-perfect" tabindex="-1">同步为什么不可能 perfect <a class="header-anchor" href="#同步为什么不可能-perfect" aria-label="Permalink to &quot;同步为什么不可能 perfect&quot;">​</a></h3><p>特殊相对论 + 信号传播 (光速 30 cm/ns) + 量子 noise 让 oracle clock 实现困难。 Google Spanner 用 GPS + 原子钟两种 independent source, 不信任单一源 (任一可失败)。 TrueTime 实际 skew bound ~1-7ms。</p><h3 id="hlc-软-bound" tabindex="-1">HLC 软 bound <a class="header-anchor" href="#hlc-软-bound" aria-label="Permalink to &quot;HLC 软 bound&quot;">​</a></h3><p>HLC 假设 NTP skew bounded by <code>max_offset</code> (CockroachDB 默认 250ms)。 Tolerate 较大 skew 但 commits 是 predictable bounded skew 而非 hard guarantee, 用 HLC + monotonic counter 维 happens-before。</p><hr><h2 id="二、truetime-api" tabindex="-1">二、TrueTime API <a class="header-anchor" href="#二、truetime-api" aria-label="Permalink to &quot;二、TrueTime API&quot;">​</a></h2><h3 id="函数签名" tabindex="-1">函数签名 <a class="header-anchor" href="#函数签名" aria-label="Permalink to &quot;函数签名&quot;">​</a></h3><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> TrueTime</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    earliest, latest </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">time</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Time</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TT.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">now</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">TrueTime</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         // {earliest, latest}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TT.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">after</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">bool</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          // t &lt; earliest</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TT.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">before</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">bool</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         // latest &lt; t</span></span></code></pre></div><p><code>now()</code> 返回一个区间, 真实 wall clock 在 <code>[earliest, latest]</code> 内。<code>after(t)</code> 表示 t 已绝对过去 (<code>t &lt; earliest</code>), <code>before(t)</code> 表示 t 已绝对未到 (<code>latest &lt; t</code>)。</p><h3 id="commit-wait-算法" tabindex="-1">Commit-Wait 算法 <a class="header-anchor" href="#commit-wait-算法" aria-label="Permalink to &quot;Commit-Wait 算法&quot;">​</a></h3><p>Spanner 写事务 commit:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. coordinator picks commit_ts = latest of TT.now()</span></span>
<span class="line"><span>2. Paxos group replicate log entry with commit_ts</span></span>
<span class="line"><span>3. coordinator waits until TT.after(commit_ts) returns true</span></span>
<span class="line"><span>   (即 earliest &gt; commit_ts, 真实时间已过 commit_ts)</span></span>
<span class="line"><span>4. reply client &quot;commit ok&quot;</span></span></code></pre></div><p>这 wait window 称 <strong>commit-wait</strong>: 大约等于 <code>latest - earliest</code> (~7ms)。等待期间保证任何 future transaction (real-time 在 commit-wait 完成后开始) 都看到 commit_ts strictly smaller than own ts → external consistency。</p><h3 id="external-consistency-形式化" tabindex="-1">External Consistency 形式化 <a class="header-anchor" href="#external-consistency-形式化" aria-label="Permalink to &quot;External Consistency 形式化&quot;">​</a></h3><p>若事务 T1 commit 在 T2 begin 之前 (按 real wall clock), 则 T1 commit_ts 必 &lt; T2 begin_ts。 这让 Spanner snapshot isolation 提供 &quot;stale read with explicit timestamp&quot; 始终正确:</p><ul><li>read at ts=t 看到所有 commit_ts ≤ t 的事务修改, 不会看到 commit 在 t 之后的修改。</li></ul><hr><h2 id="三、spanner-架构" tabindex="-1">三、Spanner 架构 <a class="header-anchor" href="#三、spanner-架构" aria-label="Permalink to &quot;三、Spanner 架构&quot;">​</a></h2><h3 id="paxos-groups" tabindex="-1">Paxos Groups <a class="header-anchor" href="#paxos-groups" aria-label="Permalink to &quot;Paxos Groups&quot;">​</a></h3><p>Spanner 把数据 sharded 到 tablets, 每 tablet 由一个 <strong>Paxos group</strong> (5 副本跨 DC) 复制。 每 group 自有 leader 与 log。</p><p>跨 tablet 事务用 <strong>2PC</strong>:</p><ul><li>Coordinator = 写锁持的 tablet group leader.</li><li>Participants = 所有被 update 的 tablet groups.</li><li>Coordinator prepare → all participants prepare → coordinator commit → all participants commit.</li></ul><p>2PC 在 Paxos group 内部 acquires Paxos commit per participant, 保证 per-tablet durability.</p><h3 id="写流程" tabindex="-1">写流程 <a class="header-anchor" href="#写流程" aria-label="Permalink to &quot;写流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>T1: BEGIN</span></span>
<span class="line"><span>  read_lock a (tablet A_paxos_group)</span></span>
<span class="line"><span>  read_lock b (tablet B_paxos_group)</span></span>
<span class="line"><span>  write a, write b</span></span>
<span class="line"><span>T1 commit:</span></span>
<span class="line"><span>  commit_ts = s = TT.now().latest</span></span>
<span class="line"><span>  prepare on A, B (Paxos group log entries with ts s)</span></span>
<span class="line"><span>  prepare ack on A, B (majority each)</span></span>
<span class="line"><span>  wait commit-wait (TT.after(s))</span></span>
<span class="line"><span>  commit ack to participants</span></span>
<span class="line"><span>  return client OK</span></span></code></pre></div><p><strong>关键点</strong>: commit-wait 不阻塞 lock (因为 prepare 已 hold locks), 仅阻塞 ack-to-client。在下 epoch 开始时, prepare 已 pile in Paxos log, 其他事务的 prepare 已 release pending locks with commit-ready state.</p><h3 id="读流程" tabindex="-1">读流程 <a class="header-anchor" href="#读流程" aria-label="Permalink to &quot;读流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>T2 read at ts t:</span></span>
<span class="line"><span>   find tablet group(s) holding data</span></span>
<span class="line"><span>   select replica (any with t-applied log) — leader or sufficiently-replicated follower</span></span>
<span class="line"><span>   wait until that replica&#39;s log has applyed up to ts t  (Paxos group leader 告知)</span></span>
<span class="line"><span>   return state at ts t</span></span></code></pre></div><p>读不需要 2PC, 单 RTT (or local from follower if log applied). 牺牲略 latency/cross-DC = read throughput 高。</p><h3 id="lock-table" tabindex="-1">Lock Table <a class="header-anchor" href="#lock-table" aria-label="Permalink to &quot;Lock Table&quot;">​</a></h3><p>Spanner 用 <strong>2PL</strong> (two-phase locking) per transaction: read locks + write locks by row。 Deadlock 检测实际至 abort 其中一个事务 (wound-wait 算法)。</p><hr><h2 id="四、truetime-硬件-attestation" tabindex="-1">四、TrueTime 硬件 Attestation <a class="header-anchor" href="#四、truetime-硬件-attestation" aria-label="Permalink to &quot;四、TrueTime 硬件 Attestation&quot;">​</a></h2><h3 id="时间源" tabindex="-1">时间源 <a class="header-anchor" href="#时间源" aria-label="Permalink to &quot;时间源&quot;">​</a></h3><p>每 DC 一组时间 reference (GPS 接收器 + 原子钟), multiple sources redundant. 若 GPS 信号短暂失, 原子钟提供 tick; 若原子钟失 (rare), GPS 提供同步; 若两都失, machine 上报 &quot;unsynchronized&quot; → fail-shut.</p><h3 id="attestation" tabindex="-1">Attestation <a class="header-anchor" href="#attestation" aria-label="Permalink to &quot;Attestation&quot;">​</a></h3><p>TrueTime API 不仅给你时间, 还伴随 <strong>trust signal</strong>: every <code>now()</code> call 米conly &quot;Trusted&quot; 时 cache time, 否则 reporting fail-shut. Shielded hardware 验证流程: GPS signal → machine encryption log → 安全 monitor 验 GPS signal 来源可信 → publish trusted node info.</p><h3 id="故障-scenarios" tabindex="-1">故障 Scenarios <a class="header-anchor" href="#故障-scenarios" aria-label="Permalink to &quot;故障 Scenarios&quot;">​</a></h3><ul><li><strong>GPS signal loss</strong>: 原子钟持相对正确时间, skew drift 累 -&gt; 30 minutes 后 fail-shut cluster. 故áo 重 human operator catch alarm.</li><li><strong>Atomic clock failure</strong>: GPS 出 stand-alone, 实际 never happens (因为 GPS 触校正 over time). Carring.....</li><li><strong>All timing failures</strong>: cluster 主动 shutdown, reject transactions. Paxos election 暂停, 防 stale time stamp commit.</li></ul><h3 id="与-hlc-attestation-比较" tabindex="-1">与 HLC attestation 比较 <a class="header-anchor" href="#与-hlc-attestation-比较" aria-label="Permalink to &quot;与 HLC attestation 比较&quot;">​</a></h3><p>HLC 没硬件 attestation, 仅 NTP 提供, 软件 monitor 必须主动检测 skew, 节点 fail exit. Spanner is strict in this sense — admin-level hardware redundancy necessary.</p><hr><h2 id="五、hlc-vs-truetime-对比矩阵" tabindex="-1">五、HLC vs TrueTime 对比矩阵 <a class="header-anchor" href="#五、hlc-vs-truetime-对比矩阵" aria-label="Permalink to &quot;五、HLC vs TrueTime 对比矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>TrueTime (Spanner)</th><th>HLC (CockroachDB)</th><th>HLC (YugaByte)</th></tr></thead><tbody><tr><td>时间源</td><td>GPS + atomic clock</td><td>NTP</td><td>NTP</td></tr><tr><td>同步精度</td><td>≤ 7ms</td><td>≤ 250ms (max_offset)</td><td>≤ 250ms</td></tr><tr><td>Commit-wait cost</td><td>~7ms (wait latest &gt; commit_ts)</td><td>不需 commit wait</td><td>不需 wait</td></tr><tr><td>External consistency</td><td>yes</td><td>no, but bounded staleness</td><td>no</td></tr><tr><td>硬件依赖</td><td>GPS 接收器 + atomic clock per DC</td><td>NTP only</td><td>NTP only</td></tr><tr><td>部署成本</td><td>高</td><td>低</td><td>低</td></tr><tr><td>适用场景</td><td>大型 cloud vendors</td><td>中型企业</td><td>中型企业</td></tr><tr><td>Stale read 防御</td><td>TrueTime API 自然防御</td><td>HLC ts invariant + read-at-ts filter</td><td>同 CockroachDB</td></tr></tbody></table><h3 id="hlc-commit-wait-不必要原因" tabindex="-1">HLC commit-wait 不必要原因 <a class="header-anchor" href="#hlc-commit-wait-不必要原因" aria-label="Permalink to &quot;HLC commit-wait 不必要原因&quot;">​</a></h3><p>HLC ts 已经是 monotonic (lt counter monotonic) + bounded pt skew, prepare 在 bgot commit time ts; 不需 commit-wait。但 HLC 让 Spanner external consistency missing — 客户端可能看到 future ts commit (newer than read at ts).</p><h3 id="cockroachdb-与-yugabyte-区别" tabindex="-1">CockroachDB 与 YugaByte 区别 <a class="header-anchor" href="#cockroachdb-与-yugabyte-区别" aria-label="Permalink to &quot;CockroachDB 与 YugaByte 区别&quot;">​</a></h3><p>CockroachDB: HLC + MVCC 在 Postgres SQL 架构。 YugaByte: PostgreSQL frontend, 但 storage 是 doc-store + Raft group, HLC 提供 Mohamed API bounds.</p><hr><h2 id="六、other-systems-与时间" tabindex="-1">六、Other Systems 与时间 <a class="header-anchor" href="#六、other-systems-与时间" aria-label="Permalink to &quot;六、Other Systems 与时间&quot;">​</a></h2><h3 id="calvin-yale-2012" tabindex="-1">Calvin (Yale 2012) <a class="header-anchor" href="#calvin-yale-2012" aria-label="Permalink to &quot;Calvin (Yale 2012)&quot;">​</a></h3><p>Calvin 离线 batch transactions, 总铁 ordering before 执行. 测 toschematically boolean balls; Kalvin时间 user-side TD-error tolerance 我 wait no, 我oracle actually per write 暂. Calvin pseudo offline 通过 batch locked a start_commit presumably use so this is awkward SAS postman now direct 性union mechan general application pins strict on 完 全 static data snapshot real-time gone 是 trans it.</p><h3 id="foundationdb" tabindex="-1">FoundationDB <a class="header-anchor" href="#foundationdb" aria-label="Permalink to &quot;FoundationDB&quot;">​</a></h3><p>FoundationDB resolve clock issues by <strong>sequencer</strong>: 一个全局 sequencer 接收 transaction 提交 timestamp monotonic. 各 client direct API 是 <code>transaction.commit()</code>: callee 拿序号顺序, 不依赖 wall clock. Linearizability 单 serializalman泽. 但是 clock-free 用 集中 bottleneck.</p><h3 id="hbase-与-accumulo" tabindex="-1">HBase 与 Accumulo <a class="header-anchor" href="#hbase-与-accumulo" aria-label="Permalink to &quot;HBase 与 Accumulo&quot;">​</a></h3><p>HBase timestamp 默认 wall clock. 已知潜在 out-of-order commit if skew; 应避免 depends on. Accumulo 同样。</p><h3 id="mongodb-clusterclock" tabindex="-1">MongoDB ClusterClock <a class="header-anchor" href="#mongodb-clusterclock" aria-label="Permalink to &quot;MongoDB ClusterClock&quot;">​</a></h3><p>MongoDB coordination node iterates&#39; logs all dependent uncommitted used 完.sequencer 含 logical 时间 integrating with physical timestamp in mingshi.</p><hr><h2 id="七、典型事故" tabindex="-1">七、典型事故 <a class="header-anchor" href="#七、典型事故" aria-label="Permalink to &quot;七、典型事故&quot;">​</a></h2><h3 id="spanner-gps-loss" tabindex="-1">Spanner GPS Loss <a class="header-anchor" href="#spanner-gps-loss" aria-label="Permalink to &quot;Spanner GPS Loss&quot;">​</a></h3><p>2015 Google 曾 talk 提到某 DC 一 GPS天线短暂失联 (暴风雨). 原子钟 hold 时间正确, 但 skew 渐累. Spanner 5 minutes 后上inia 类 fail-fast alert, operator 处理恢复 GPS.</p><h3 id="cockroachdb-ntp-skew-storm" tabindex="-1">CockroachDB NTP Skew Storm <a class="header-anchor" href="#cockroachdb-ntp-skew-storm" aria-label="Permalink to &quot;CockroachDB NTP Skew Storm&quot;">​</a></h3><p>2018 用户报告 CockroachDB cluster slow queries 因为 3 节点 NTP skew 超过 max_offset (250ms), cluster nodes 拒⚭ 异 relation offset rejected; team修改 cron ntpdate to keep drift &lt; 50ms.</p><h3 id="mongodb-clock-skew-写丢失" tabindex="-1">MongoDB Clock Skew 写丢失 <a class="header-anchor" href="#mongodb-clock-skew-写丢失" aria-label="Permalink to &quot;MongoDB Clock Skew 写丢失&quot;">​</a></h3><p>MongoDB replica set wall-clock-based timestamp 排序 commit, 某 node skew 后写 后 损 ye叙述 丢失现象. 多个 issue reported in MongoDB Jira (2016); fix: use logical timestamp in replication log。</p><hr><h2 id="八、易错清单" tabindex="-1">八、易错清单 <a class="header-anchor" href="#八、易错清单" aria-label="Permalink to &quot;八、易错清单&quot;">​</a></h2><ol><li><strong>TrueTime 不是 oracle</strong>: 你必须 commit-wait 第三方 before reply。 没 commit-wait, external consistency违反。</li><li><strong>Spanner 不只 TrueTime</strong>: 还有 Paxos + 2PC + Lock table + 4PL, TrueTime 给时间戳正确性.</li><li><strong>HLC commit-wait 是 optional</strong>: HLC upper bound 不 wait, 但 staleness bounded by max_offset。 业务可接受 weak consistency 才用 HLC。</li><li><strong>CockroachDB 写入突然不再 单一 well ordered</strong>: HLC across region 可能违反 real-time order, 仅 per transaction opertion的关系保 happens-before.</li><li><strong>GPS 必须 multi-source</strong>: 单 GPS source 故障 → cluster unsynced, 多源故障 fail-shut. Spanner 至少 2 GPS + 2 原子钟 per DC。</li><li><strong>Clock 政府 aware NTP 与ictschronous 数据 Illegal</strong>: NTP 可以 使 节点 clock backward. HLC 算法若 都 没 caught backward clock navigate 上 partial 可能 导致 Haremix ts broken; cockroach supports NTP sane 版本 with proper monotonous rate.</li></ol><hr><h2 id="九、这一章带走的东西" tabindex="-1">九、这一章带走的东西 <a class="header-anchor" href="#九、这一章带走的东西" aria-label="Permalink to &quot;九、这一章带走的东西&quot;">​</a></h2><ol><li>TrueTime 给 [earliest, latest] uncertainty API, commit-wait 让 commit_ts guarantee strictly 小于 future begin_ts ⇒ external consistency。</li><li>Google Spanner 是 industrial 实现的 Paxos group + 2PC + commit-wait + TrueTime。</li><li>HLC 是 software-only fallback, NTP skew bounded; 但 external consistency 仅近似, 真正实时保证仍硬件 sync 需要.</li><li>Clock attestation (GPS + atomic) 让硬件 fail-shut 安全; 没建 monotonic hardware 就 not safe.</li><li>CockroachDB / YugaByte 用 HLC 取代 TrueTime, 同十字低部署成本 不保 external consistency strict 2PL-fence only serializable + bounded staleness.</li><li>FoundationDB 用 sequencer 节约 wall clock 量 importance; 中央 sequencer serializing 是车另 第四百 srullt. 用 distributed 省ariesle clock alternative.</li></ol><hr><p>下一节 → <a href="./dag">DAG、git、blockchain 的序</a></p>`,81)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
